using System;
using System.Collections.Generic;
using LittleLeo;
using UnityEngine;
using UnityEngine.EventSystems;

namespace Astrea.GameStates;

[CreateAssetMenu(fileName = "OnMouseOverChooseTarget", menuName = "Data/Battle/Actions/OnMouseOver Choose Target")]
public class OnMouseOverChooseTarget : Action
{
	[Header("Targets")]
	[SerializeField]
	private List<TargetEnum> targetUnits;

	[SerializeField]
	protected bool chooseSelf;

	[NonSerialized]
	private TargetInstance previouslyRaycastResult;

	public void OnReset()
	{
		previouslyRaycastResult = null;
	}

	public override void Execute(float d)
	{
		List<RaycastResult> uIObjectsOverMouse = MouseInputUtility.GetUIObjectsOverMouse();
		TargetInstance targetInstance = null;
		if (uIObjectsOverMouse.Count > 0)
		{
			targetInstance = uIObjectsOverMouse.First().gameObject.GetComponent<TargetInstance>();
		}
		if (targetInstance != null && previouslyRaycastResult == null)
		{
			if (chooseSelf)
			{
				if (targetInstance.transform.parent.gameObject != base.actionInstance.ActionOwner)
				{
					return;
				}
			}
			else if (!targetUnits.Contains(targetInstance.TargetEnum))
			{
				return;
			}
			targetInstance.OnMouseOver();
			previouslyRaycastResult = targetInstance;
		}
		if (previouslyRaycastResult != null && previouslyRaycastResult != targetInstance && previouslyRaycastResult.gameObject.activeInHierarchy)
		{
			previouslyRaycastResult.gameObject.GetComponent<TargetInstance>().OnMouseExit();
			previouslyRaycastResult = null;
		}
	}
}
